const wb=Workbook.create();const specs=[];let tableNo=0;
function base(name,title,note){const s=wb.worksheets.add(name);s.showGridLines=false;s.getRange('A1:H3').format.font={name:'Arial',size:11};s.getRange('A1:H1').merge();s.getRange('A1').values=[[title]];s.getRange('A1').format.font={name:'Arial',size:17,bold:true,color:'#172B4D'};s.getRange('A1:H1').format.rowHeight=30;s.getRange('A2:H3').merge();s.getRange('A2').values=[[note]];s.getRange('A2:H3').format={wrapText:true,font:{name:'Arial',size:10,color:'#556477'},verticalAlignment:'center',rowHeight:20};s.getRange('A1:H3').format.columnWidth=21;specs.push({name,s,sections:[]});return s;}
function band(s,r,text){const x=s.getRangeByIndexes(r,0,1,8);x.merge();x.values=[[text]];x.format={fill:'#E7EDF4',font:{name:'Arial',size:12,bold:true,color:'#172B4D'},rowHeight:27};}
function note(s,r,label,text){s.getCell(r,0).values=[[label]];s.getRangeByIndexes(r,1,1,7).merge();s.getCell(r,1).values=[[text]];s.getRangeByIndexes(r,0,1,8).format={font:{name:'Arial',size:10,color:'#344054'},wrapText:true,verticalAlignment:'top',rowHeight:Math.max(32,Math.ceil(text.length/128)*15+10)};s.getCell(r,0).format.font.bold=true;}
function table(s,r,cols,rows){if(rows.some(x=>x.length!==cols.length))throw Error('Column mismatch '+s.name+' '+cols);const n=cols.length;s.getRangeByIndexes(r,0,1,n).values=[cols];s.getRangeByIndexes(r+1,0,rows.length,n).values=rows;const a=s.getRangeByIndexes(r,0,rows.length+1,n);a.format={font:{name:'Arial',size:10},wrapText:true,verticalAlignment:'top',rowHeight:48};s.getRangeByIndexes(r,0,1,n).format={fill:'#243B53',font:{name:'Arial',size:10,bold:true,color:'#FFFFFF'},rowHeight:36,wrapText:true};const name='MenuTable'+(++tableNo);s.tables.add(`A${r+1}:${String.fromCharCode(64+n)}${r+rows.length+1}`,true,name);cols.forEach((c,i)=>{if(c.includes('Rp'))s.getRangeByIndexes(r+1,i,rows.length,1).setNumberFormat('#,##0;[Red](#,##0);"—"');if(rows.some(x=>x[i] instanceof Date))s.getRangeByIndexes(r+1,i,rows.length,1).setNumberFormat('dd mmm yyyy');});return r+rows.length+2;}

